export const roomPoints=r=>r.points||[[0,0],[r.w,0],[r.w,r.d],[0,r.d]];
export function ringArea(p){return Math.abs(p.reduce((s,a,i)=>{const b=p[(i+1)%p.length];return s+a[0]*b[1]-b[0]*a[1];},0))/2;}
export const roomArea=r=>ringArea(roomPoints(r))-(r.holes||[]).reduce((s,h)=>s+ringArea(h),0);
export function inRing(p,x,z){let inside=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
export const inRoom=(r,x,z)=>inRing(roomPoints(r),x-r.x,z-r.z)&&!(r.holes||[]).some(h=>inRing(h,x-r.x,z-r.z));
export function validateRoomPolygon(r){if(!r.points&&!r.holes)return;if(r.holes&&(!Array.isArray(r.holes)||r.holes.length>32))throw Error('Invalid room holes.');const rings=[roomPoints(r),...(r.holes||[])];for(const p of rings){if(!Array.isArray(p)||p.length<3||p.length>2048||p.some(a=>!Array.isArray(a)||a.length!==2||!a.every(Number.isFinite)||a[0]<0||a[1]<0||a[0]>r.w+.001||a[1]>r.d+.001)||ringArea(p)<.01)throw Error('Invalid polygon room boundary.');if(new Set(p.map(a=>a.join(','))).size!==p.length)throw Error('Room polygon repeats a vertex.');for(let i=0;i<p.length;i++)for(let j=i+2;j<p.length;j++){if(i===0&&j===p.length-1)continue;if(touches(p[i],p[(i+1)%p.length],p[j],p[(j+1)%p.length]))throw Error('Room polygon crosses itself.');}}for(let i=1;i<rings.length;i++)for(let j=0;j<i;j++){for(let a=0;a<rings[i].length;a++)for(let b=0;b<rings[j].length;b++)if(touches(rings[i][a],rings[i][(a+1)%rings[i].length],rings[j][b],rings[j][(b+1)%rings[j].length]))throw Error('Room hole crosses another boundary.');if(j>0&&(inRing(rings[i],...rings[j][0])||inRing(rings[j],...rings[i][0])))throw Error('Room holes overlap.');}if(roomArea(r)<=.01)throw Error('Room has no usable surface.');for(const h of r.holes||[])if(h.some(a=>!inRing(roomPoints(r),a[0],a[1])))throw Error('Room hole lies outside its boundary.');}
function cross(a,b,c,d){const side=(p,q,r)=>(q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0]);return side(a,b,c)*side(a,b,d)<0&&side(c,d,a)*side(c,d,b)<0;}
export function roomPath(r){const path=p=>'M'+p.map(a=>`${a[0]+r.x},${a[1]+r.z}`).join(' L')+' Z';return [roomPoints(r),...(r.holes||[])].map(path).join(' ');}
export function roomsOverlap(a,b){if(a.x>=b.x+b.w||b.x>=a.x+a.w||a.z>=b.z+b.d||b.z>=a.z+a.d)return false;const world=r=>roomPoints(r).map(p=>[p[0]+r.x,p[1]+r.z]);const ap=world(a),bp=world(b);for(let i=0;i<ap.length;i++)for(let j=0;j<bp.length;j++)if(cross(ap[i],ap[(i+1)%ap.length],bp[j],bp[(j+1)%bp.length]))return true;for(const r of [a,b])for(const ring of [roomPoints(r),...(r.holes||[])])for(let i=0;i<ring.length;i++){const p=ring[i],q=ring[(i+1)%ring.length],length=Math.hypot(q[0]-p[0],q[1]-p[1]);if(!length)continue;for(const sign of [-1,1]){const x=r.x+(p[0]+q[0])/2+sign*(q[1]-p[1])/length*.001,z=r.z+(p[1]+q[1])/2-sign*(q[0]-p[0])/length*.001;if(inRoom(a,x,z)&&inRoom(b,x,z))return true;}}return false;}

function touches(a,b,c,d){if(cross(a,b,c,d))return true;const on=(p,q,r)=>Math.abs((q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0]))<1e-8&&r[0]>=Math.min(p[0],q[0])-1e-8&&r[0]<=Math.max(p[0],q[0])+1e-8&&r[1]>=Math.min(p[1],q[1])-1e-8&&r[1]<=Math.max(p[1],q[1])+1e-8;return on(a,b,c)||on(a,b,d)||on(c,d,a)||on(c,d,b);}

export const roomEdges=r=>[roomPoints(r),...(r.holes||[])].flatMap(ring=>ring.map((a,i)=>{const b=ring[(i+1)%ring.length];return [r.x+a[0],r.z+a[1],r.x+b[0],r.z+b[1]];}));
